package com.creditsense.config;
import com.creditsense.domain.*; import com.creditsense.repo.Repositories; import org.springframework.boot.CommandLineRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal;
@Configuration @ConditionalOnProperty(name="app.demo-mode",havingValue="true") public class DemoSeed { @Bean CommandLineRunner seed(Repositories.Users users,Repositories.Applicants applicants,Repositories.Applications applications, PasswordEncoder passwords){return args->{seedUser(users,passwords,"applicant@creditsense.demo",Role.APPLICANT);seedUser(users,passwords,"officer@creditsense.demo",Role.LOAN_OFFICER);seedUser(users,passwords,"admin@creditsense.demo",Role.ADMIN);if(applications.count()==0){seedApp(users,applicants,applications,passwords,"apex@creditsense.demo","Apex Components","AAPFU0939F",new BigDecimal("850000"),AppStatus.COMPLIANCE_REVIEW);seedApp(users,applicants,applications,passwords,"harbor@creditsense.demo","Harbor Retail","ABCDE1234F",new BigDecimal("420000"),AppStatus.SUBMITTED);seedApp(users,applicants,applications,passwords,"northstar@creditsense.demo","Northstar Build","PQRSX9876Z",new BigDecimal("1200000"),AppStatus.COMPLIANCE_FAILED);}};} private void seedUser(Repositories.Users users,PasswordEncoder p,String email,Role role){if(users.findByEmail(email).isEmpty())users.save(new User(email,p.encode("DemoPass123!"),role));} private void seedApp(Repositories.Users users,Repositories.Applicants applicants,Repositories.Applications applications,PasswordEncoder p,String email,String name,String pan,BigDecimal amount,AppStatus status){seedUser(users,p,email,Role.APPLICANT);User u=users.findByEmail(email).orElseThrow();Applicant a=new Applicant();a.setUser(u);a.setBusinessName(name);a.setPan(pan);a.setGstin("27AAPFU0939F1ZV");a.setAddress("17 Market Road, Pune, Maharashtra 411001");applicants.save(a);LoanApplication app=new LoanApplication();app.setApplicant(a);app.setAmountRequested(amount);app.setPurpose("Working capital");app.setStatus(status);app.setFeatureVector("{\"business_vintage_years\":6.2,\"monthly_revenue\":1800000,\"revenue_volatility\":0.18,\"gst_filing_consistency\":0.78,\"debt_to_revenue_ratio\":0.34,\"inflow_outflow_ratio\":1.12,\"average_bank_balance\":230000,\"trade_references\":8,\"delinquency_buckets\":2,\"loan_to_revenue_ratio\":0.47,\"sector\":\"manufacturing\",\"kyc_completeness_score\":1.0,\"digital_transaction_frequency\":210}");applications.save(app);} }
